def cli_guild(name, tibiadata, json):
    """Displays information about a Tibia guild."""
    guild = tibiadata.guilds.get_guild(name)
    if guild is None:
        return tibiapy_common.tibia_em(f"I don't know about a guild named {name}.")
    if json:
        return tibiapy_common.tibia_em(guild.json(indent=4))
    embed = discord.Embed(title=f"{guild.name} ({guild.world} - {guild.rank})",
                          description=guild.description, color=tibiapy_common.COLOR_MAIN)
    embed.set_thumbnail(url=guild.emblem.url)
    embed.add_field(name="Level", value=guild.level)
    embed.add_field(name="Members", value=guild.members)
    embed.add_field(name="Rank", value=guild.rank)
    embed.add_field(name="Location", value=guild.location)
    embed.add_field(name="Last Activity", value=guild.last_activity)
    return tibiapy_common.tibia_em(embed)

