def cli_guild_members(name, tibiadata, json):
    """Displays information about a Tibia guild members."""
    guild = tibiadata.guilds.get_guild(name)
    if guild is None:
        return tibiapy_common.tibia_em(f"I don't know about a guild named {name}.")
    if json:
        return tibiapy_common.tibia_em(guild.members_json(indent=4))
    embed = discord.Embed(title=f"{guild.name} Members", color=tibiapy_common.COLOR_MAIN)
    for member in guild.members:
        embed.add_field(name=member.name, value=member.level, inline=True)
    return tibiapy_common.tibia_em(embed)


